"""内置默认主题资源。"""
STYLE_CSS = "/* ============================================================\n   MDW 主题样式 —— Material Design 3（Material You）风格\n   设计要点：\n     - 高版本安卓质感：柔和色板、大圆角、层级阴影、状态层\n     - 顶栏（App Bar）：内容区顶部固定，滚动时浮现阴影\n     - 侧边栏（Navigation Drawer）：Material 托盘，可整体收起\n     - 分组折叠：grid 0fr→1fr 过渡 + 内容淡入淡出（强调缓动）\n     - 涟漪（ripple）由 app.js 注入 .mdw-ripple 元素\n     - 所有图标用 CSS 绘制，不依赖字形\n   ============================================================ */\n\n/* ── 1. 设计令牌（Material 3 浅色） ─────────────────── */\n:root {\n  /* 颜色 */\n  --primary: #6750a4;\n  --on-primary: #ffffff;\n  --primary-container: #eaddff;\n  --on-primary-container: #21005d;\n  --secondary: #625b71;\n  --on-secondary: #ffffff;\n  --secondary-container: #e8def8;\n  --on-secondary-container: #1d192b;\n  --tertiary-container: #ffd8e4;\n  --error: #b3261e;\n  --error-container: #f9dedc;\n  --on-error-container: #410e0b;\n\n  --surface: #fef7ff;\n  --surface-container-lowest: #ffffff;\n  --surface-container-low: #f7f2fa;\n  --surface-container: #f3edf7;\n  --surface-container-high: #ece6f0;\n  --surface-container-highest: #e6e0e9;\n  --on-surface: #1d1b20;\n  --on-surface-variant: #49454f;\n  --outline: #79747e;\n  --outline-variant: #cac4d0;\n  --scrim: rgba(0, 0, 0, 0.5);\n  --inverse-surface: #322f35;\n  --inverse-on-surface: #f5eff7;\n\n  /* 状态层（Material 状态叠加） */\n  --state-hover: rgba(29, 27, 32, 0.08);\n  --state-pressed: rgba(29, 27, 32, 0.12);\n\n  /* 信息块（tonal 色组） */\n  --note-bg: #d8e2ff;    --note-border: #2952cc; --note-fg: #001945;\n  --info-bg: #ccebf7;    --info-border: #0077a8; --info-fg: #003546;\n  --tip-bg: #bfe9c8;     --tip-border: #006d31;  --tip-fg: #003b12;\n  --warning-bg: #ffe3b8; --warning-border: #8f4e00; --warning-fg: #3e2a00;\n  --danger-bg: #ffdad6;  --danger-border: #ba1a1a;  --danger-fg: #410002;\n\n  /* 代码 */\n  --code-bg: #322f35;\n  --code-text: #f5eff7;\n  --code-inline-bg: #e8def8;\n  --code-inline-text: #1d192b;\n\n  /* 形状（Material 3 Shape） */\n  --shape-xs: 4px;\n  --shape-sm: 8px;\n  --shape-md: 12px;\n  --shape-lg: 16px;\n  --shape-xl: 28px;\n\n  /* 阴影（Material 3 Elevation） */\n  --elevation-1: 0 1px 2px rgba(0, 0, 0, 0.3), 0 1px 3px 1px rgba(0, 0, 0, 0.15);\n  --elevation-2: 0 1px 2px rgba(0, 0, 0, 0.3), 0 2px 6px 2px rgba(0, 0, 0, 0.15);\n  --elevation-3: 0 4px 8px 3px rgba(0, 0, 0, 0.15), 0 1px 3px rgba(0, 0, 0, 0.3);\n\n  /* 动效（Material 3 Motion） */\n  --ease-standard: cubic-bezier(0.2, 0, 0, 1);\n  --ease-emphasized: cubic-bezier(0.05, 0.7, 0.1, 1);\n  --dur: 0.3s;\n\n  /* 字体 */\n  --font-sans: \"Inter\", system-ui, -apple-system, \"Segoe UI\", Roboto,\n    \"Helvetica Neue\", \"PingFang SC\", \"Hiragino Sans GB\",\n    \"Microsoft YaHei\", \"Noto Sans CJK SC\", \"Noto Sans SC\", sans-serif;\n  --font-mono: \"JetBrains Mono\", \"SF Mono\", \"Fira Code\", Consolas,\n    \"Courier New\", monospace;\n\n  /* 布局 */\n  --sidebar-w: 320px;\n  --content-max: 860px;\n  --appbar-h: 64px;\n}\n\n/* ── 1b. 设计令牌（Material 3 深色） ─────────────────── */\n@media (prefers-color-scheme: dark) {\n  :root {\n    --primary: #d0bcff;\n    --on-primary: #381e72;\n    --primary-container: #4f378b;\n    --on-primary-container: #eaddff;\n    --secondary: #ccc2dc;\n    --on-secondary: #332d41;\n    --secondary-container: #4a4458;\n    --on-secondary-container: #e8def8;\n    --tertiary-container: #633b48;\n    --error: #f2b8b5;\n    --error-container: #8c1d18;\n    --on-error-container: #f9dedc;\n\n    --surface: #141218;\n    --surface-container-lowest: #0f0d13;\n    --surface-container-low: #1d1b20;\n    --surface-container: #211f26;\n    --surface-container-high: #2b2930;\n    --surface-container-highest: #36343b;\n    --on-surface: #e6e0e9;\n    --on-surface-variant: #cac4d0;\n    --outline: #938f99;\n    --outline-variant: #49454f;\n    --inverse-surface: #e6e0e9;\n    --inverse-on-surface: #322f35;\n\n    --state-hover: rgba(230, 224, 233, 0.08);\n    --state-pressed: rgba(230, 224, 233, 0.12);\n\n    --note-bg: #284777;    --note-border: #aecbff; --note-fg: #d8e2ff;\n    --info-bg: #005e73;    --info-border: #4fd8eb; --info-fg: #ccebf7;\n    --tip-bg: #005e2e;     --tip-border: #83d99e; --tip-fg: #bfe9c8;\n    --warning-bg: #665000; --warning-border: #ffc46b; --warning-fg: #ffe3b8;\n    --danger-bg: #93000a;  --danger-border: #ffb4ab; --danger-fg: #ffdad6;\n\n    --code-bg: #0f0d13;\n    --code-text: #e6e0e9;\n    --code-inline-bg: #4a4458;\n    --code-inline-text: #e8def8;\n  }\n}\n\n/* ── 2. 基础 ─────────────────────────────────────────── */\n* { margin: 0; padding: 0; box-sizing: border-box; }\n\nhtml { scroll-behavior: smooth; scroll-padding-top: calc(var(--appbar-h) + 24px); }\n\n* { margin: 0; padding: 0; box-sizing: border-box; }\n\nbody {\n  font-family: var(--font-sans);\n  background: var(--surface);\n  color: var(--on-surface);\n  line-height: 1.75;\n  font-size: 16px;\n  font-weight: 550;\n  -webkit-font-smoothing: antialiased;\n  text-rendering: optimizeLegibility;\n}\n\n::selection { background: var(--primary-container); }\n\n:focus-visible {\n  outline: 3px solid var(--primary);\n  outline-offset: 2px;\n  border-radius: var(--shape-sm);\n}\n\na { color: var(--primary); text-decoration: none; }\na:hover { text-decoration: underline; }\n\nbutton { font-family: inherit; }\n\n.mdw-layout { min-height: 100vh; }\n\n/* ── 3. 顶部应用栏（App Bar） ─────────────────────────── */\n.mdw-appbar {\n  position: fixed;\n  top: 0;\n  right: 0;\n  left: var(--sidebar-w);\n  height: var(--appbar-h);\n  z-index: 50;\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  padding: 0 16px;\n  background: var(--surface);\n  transition: left var(--dur) var(--ease-emphasized),\n              box-shadow 0.25s var(--ease-standard);\n}\nbody.nav-collapsed .mdw-appbar { left: 0; }\n.mdw-appbar.scrolled { box-shadow: var(--elevation-2); }\n\n.mdw-appbar-title {\n  margin-left: 8px;\n  font-size: 22px;\n  font-weight: 600;\n  letter-spacing: 0;\n  color: var(--on-surface);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n/* ── 4. 汉堡按钮（CSS 绘制三条横线 + 变形动画） ─────── */\n.mdw-sidenav-btn {\n  position: relative;\n  flex-shrink: 0;\n  width: 48px;\n  height: 48px;\n  border: none;\n  background: transparent;\n  border-radius: 50%;\n  color: var(--on-surface);\n  cursor: pointer;\n  overflow: hidden;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 5px;\n  transition: background 0.2s var(--ease-standard);\n}\n.mdw-sidenav-btn:hover { background: var(--state-hover); }\n.mdw-sidenav-btn:active { background: var(--state-pressed); }\n\n.mdw-sidenav-btn .mdw-bar {\n  display: block;\n  width: 20px;\n  height: 3px;\n  border-radius: 2px;\n  background: currentColor;\n  transition: transform var(--dur) var(--ease-emphasized),\n              opacity 0.2s var(--ease-standard);\n}\n\n/* 移动端抽屉打开时：三条横线变形为 ✕ */\nbody.nav-open .mdw-sidenav-btn .mdw-bar:nth-child(1) { transform: translateY(8px) rotate(45deg); }\nbody.nav-open .mdw-sidenav-btn .mdw-bar:nth-child(2) { opacity: 0; }\nbody.nav-open .mdw-sidenav-btn .mdw-bar:nth-child(3) { transform: translateY(-8px) rotate(-45deg); }\n\n/* ── 5. 侧边栏（Navigation Drawer） ──────────────────── */\n.mdw-nav {\n  position: fixed;\n  left: 0;\n  top: 0;\n  bottom: 0;\n  width: var(--sidebar-w);\n  z-index: 60;\n  display: flex;\n  flex-direction: column;\n  background: var(--surface-container-low);\n  color: var(--on-surface-variant);\n  overflow: hidden;\n  transition: transform var(--dur) var(--ease-emphasized);\n}\nbody.nav-collapsed .mdw-nav { transform: translateX(-100%); }\n\n.mdw-nav-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 20px 16px 10px 28px;\n  flex-shrink: 0;\n}\n.mdw-nav-brand {\n  font-size: 22px;\n  font-weight: 650;\n  letter-spacing: 0;\n  color: var(--on-surface);\n}\n\n/* 关闭按钮：CSS 绘制 ✕（移动端抽屉显示） */\n.mdw-nav-close {\n  display: none;\n  width: 40px;\n  height: 40px;\n  position: relative;\n  background: transparent;\n  border: none;\n  border-radius: 50%;\n  color: var(--on-surface-variant);\n  cursor: pointer;\n  overflow: hidden;\n}\n.mdw-nav-close::before,\n.mdw-nav-close::after {\n  content: \"\";\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  width: 16px;\n  height: 2px;\n  border-radius: 1px;\n  background: currentColor;\n}\n.mdw-nav-close::before { transform: translate(-50%, -50%) rotate(45deg); }\n.mdw-nav-close::after  { transform: translate(-50%, -50%) rotate(-45deg); }\n.mdw-nav-close:hover { background: var(--state-hover); color: var(--on-surface); }\n\n.mdw-nav-body {\n  flex: 1;\n  overflow-y: auto;\n  padding: 4px 12px 32px;\n}\n.mdw-nav-body::-webkit-scrollbar { width: 6px; }\n.mdw-nav-body::-webkit-scrollbar-thumb { background: var(--outline-variant); border-radius: 3px; }\n.mdw-nav-body::-webkit-scrollbar-track { background: transparent; }\n\n/* ── 6. 导航树 ───────────────────────────────────────── */\n.mdw-nav-tree { list-style: none; }\n\n.mdw-nav-group { margin: 2px 0; }\n\n/* 分组子树：grid 0fr→1fr 折叠动画 + 内容淡入淡出 */\n.mdw-nav-tree-wrap {\n  display: grid;\n  grid-template-rows: 1fr;\n  transition: grid-template-rows 0.35s var(--ease-emphasized);\n}\n.mdw-nav-group.collapsed > .mdw-nav-tree-wrap { grid-template-rows: 0fr; }\n.mdw-nav-tree-inner {\n  overflow: hidden;\n  min-height: 0;\n  transition: opacity 0.2s var(--ease-standard);\n}\n.mdw-nav-group.collapsed > .mdw-nav-tree-wrap .mdw-nav-tree-inner { opacity: 0; }\n.mdw-nav-tree-inner > .mdw-nav-tree { padding-left: 14px; }\n\n.mdw-nav-row {\n  position: relative;\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  min-height: 48px;\n  border-radius: var(--shape-xl);\n  overflow: hidden;\n  transition: background 0.2s var(--ease-standard);\n}\n.mdw-nav-row:hover { background: var(--state-hover); }\n\n.mdw-nav-link,\n.mdw-nav-dir {\n  flex: 1;\n  align-self: stretch;\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  min-width: 0;\n  padding: 0 16px;\n  border-radius: var(--shape-xl);\n  font-size: 14px;\n  font-weight: 550;\n  color: var(--on-surface-variant);\n  text-decoration: none;\n  overflow: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n  cursor: pointer;\n  transition: background 0.2s var(--ease-standard),\n              color 0.2s var(--ease-standard);\n}\n.mdw-nav-link span,\n.mdw-nav-dir span { overflow: hidden; text-overflow: ellipsis; }\n.mdw-nav-link:hover { color: var(--on-surface); text-decoration: none; }\n.mdw-nav-link.active,\n.mdw-nav-dir.active {\n  background: var(--secondary-container);\n  color: var(--on-secondary-container);\n  font-weight: 650;\n}\n.mdw-nav-dir { font-weight: 650; }\n.mdw-nav-icon { font-size: 14px; flex-shrink: 0; }\n\n/* 分组折叠箭头：CSS 绘制 ▸ / ▾（旋转过渡） */\n.mdw-nav-toggle {\n  flex-shrink: 0;\n  width: 40px;\n  height: 40px;\n  border: none;\n  background: transparent;\n  color: var(--on-surface-variant);\n  cursor: pointer;\n  border-radius: 50%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  transition: background 0.2s var(--ease-standard);\n}\n.mdw-nav-toggle::before {\n  content: \"\";\n  width: 9px;\n  height: 9px;\n  border-right: 2px solid currentColor;\n  border-bottom: 2px solid currentColor;\n  transform: rotate(-45deg); /* 收起态：▸ 向右 */\n  transition: transform 0.35s var(--ease-emphasized);\n}\n.mdw-nav-group:not(.collapsed) > .mdw-nav-row .mdw-nav-toggle::before {\n  transform: rotate(45deg); /* 展开态：▾ 向下 */\n}\n.mdw-nav-toggle:hover { background: var(--state-hover); color: var(--on-surface); }\n\n/* ── 7. 主内容 ───────────────────────────────────────── */\n.mdw-content {\n  margin-left: var(--sidebar-w);\n  padding: calc(var(--appbar-h) + 28px) clamp(20px, 5vw, 56px) 56px;\n  max-width: calc(var(--content-max) + var(--sidebar-w));\n  min-width: 0;\n  transition: margin-left var(--dur) var(--ease-emphasized);\n  animation: mdw-fade-up 0.45s var(--ease-emphasized) both;\n}\nbody.nav-collapsed .mdw-content { margin-left: 0; }\n\n.mdw-content--bare {\n  margin-left: 0;\n  margin-right: auto;\n  max-width: var(--content-max);\n  padding-top: 96px;\n}\n\n.mdw-content h1,\n.mdw-content h2,\n.mdw-content h3,\n.mdw-content h4,\n.mdw-content h5,\n.mdw-content h6,\n.mdw-content .mdw-h1,\n.mdw-content .mdw-h2,\n.mdw-content .mdw-h3,\n.mdw-content .mdw-h4,\n.mdw-content .mdw-h5,\n.mdw-content .mdw-h6 {\n  font-weight: 650;\n  line-height: 1.3;\n  letter-spacing: 0;\n  scroll-margin-top: calc(var(--appbar-h) + 24px);\n  position: relative;\n}\n.mdw-content h1, .mdw-content .mdw-h1 { font-size: 32px; font-weight: 700; margin: 0 0 0.6em; }\n.mdw-content h2, .mdw-content .mdw-h2 { font-size: 28px; font-weight: 700; margin: 1.6em 0 0.5em; }\n.mdw-content h3, .mdw-content .mdw-h3 { font-size: 24px; font-weight: 650; margin: 1.4em 0 0.45em; }\n.mdw-content h4, .mdw-content .mdw-h4 { font-size: 22px; font-weight: 650; margin: 1.3em 0 0.4em; }\n.mdw-content h5, .mdw-content .mdw-h5 { font-size: 16px; font-weight: 650; margin: 1.2em 0 0.35em; }\n.mdw-content h6, .mdw-content .mdw-h6 { font-size: 14px; font-weight: 650; margin: 1.1em 0 0.3em; color: var(--on-surface-variant); }\n\n/* 标题锚点链接：hover 时显示 # 图标 */\n.mdw-content h1[id]::before,\n.mdw-content h2[id]::before,\n.mdw-content h3[id]::before,\n.mdw-content h4[id]::before,\n.mdw-content h5[id]::before,\n.mdw-content h6[id]::before {\n  content: \"#\";\n  position: absolute;\n  left: -1.1em;\n  font-size: 0.8em;\n  color: var(--primary);\n  opacity: 0;\n  transition: opacity 0.15s ease;\n  font-weight: 500;\n}\n.mdw-content h1[id]:hover::before,\n.mdw-content h2[id]:hover::before,\n.mdw-content h3[id]:hover::before,\n.mdw-content h4[id]:hover::before,\n.mdw-content h5[id]:hover::before,\n.mdw-content h6[id]:hover::before {\n  opacity: 0.6;\n}\n\n.mdw-content p { margin-bottom: 1.05em; }\n.mdw-content ul,\n.mdw-content ol,\n.mdw-content .mdw-list { margin: 0 0 1.1em; padding-left: 1.6em; }\n.mdw-content li { margin-bottom: 0.35em; }\n.mdw-content li::marker { color: var(--on-surface-variant); }\n.mdw-content .mdw-list-ordered { list-style-type: decimal; }\n\n.mdw-content blockquote,\n.mdw-content .mdw-blockquote {\n  margin: 1.1em 0;\n  padding: 0.6em 0 0.6em 18px;\n  border-left: 4px solid var(--primary);\n  color: var(--on-surface-variant);\n  background: var(--surface-container-low);\n  border-radius: 0 var(--shape-sm) var(--shape-sm) 0;\n}\n.mdw-content blockquote p,\n.mdw-content .mdw-blockquote p { margin-bottom: 0.5em; }\n.mdw-content blockquote p:last-child,\n.mdw-content .mdw-blockquote p:last-child { margin-bottom: 0; }\n\n.mdw-content hr,\n.mdw-content .mdw-hr {\n  border: none;\n  border-top: 1px solid var(--outline-variant);\n  margin: 2em 0;\n}\n\n/* ── GFM 扩展样式 ── */\n/* 任务列表 */\n.mdw-task-list { list-style: none; padding-left: 0.4em; }\n.mdw-task-item { display: flex; align-items: baseline; gap: 8px; }\n.mdw-task-item input[type=\"checkbox\"] {\n  flex-shrink: 0;\n  width: 16px; height: 16px;\n  margin-top: 0.3em;\n  accent-color: var(--primary);\n  pointer-events: none;\n}\n\n/* 标记高亮 */\n.mdw-content mark {\n  background: var(--primary-container);\n  color: var(--on-primary-container);\n  padding: 0.1em 0.35em;\n  border-radius: 3px;\n}\n\n/* 上下标 */\n.mdw-content sup, .mdw-content sub { font-size: 0.8em; }\n.mdw-content sup { vertical-align: super; }\n.mdw-content sub { vertical-align: sub; }\n\n/* 脚注 */\n.mdw-footnote-sep { margin: 2.5em 0 1em; width: 30%; }\n.mdw-footnotes { font-size: 0.9em; color: var(--on-surface-variant); }\n.mdw-footnotes ol { padding-left: 1.2em; }\n.mdw-footnotes li { margin-bottom: 0.5em; }\n.mdw-footnote-ref a { text-decoration: none; font-weight: 600; }\n.mdw-footnote-backref { text-decoration: none; margin-left: 4px; }\n\n/* 数学公式 */\n.mdw-math-block {\n  display: block;\n  overflow-x: auto;\n  padding: 16px 20px;\n  margin: 1.2em 0;\n  background: var(--surface-container-low);\n  border-radius: var(--shape-md);\n  font-family: var(--font-mono);\n  font-size: 0.95em;\n  text-align: center;\n}\n.mdw-math-inline {\n  font-family: var(--font-mono);\n  font-size: 0.95em;\n  background: var(--surface-container-low);\n  padding: 0.1em 0.3em;\n  border-radius: 3px;\n}\n\n/* TOC 目录 */\n.mdw-toc {\n  background: var(--surface-container-low);\n  border: 1px solid var(--outline-variant);\n  border-radius: var(--shape-md);\n  padding: 16px 20px;\n  margin: 1.2em 0;\n}\n.mdw-toc ul { list-style: none; padding: 0; margin: 0; }\n.mdw-toc ul ul { padding-left: 1.2em; }\n.mdw-toc li { margin-bottom: 4px; }\n.mdw-toc a { text-decoration: none; font-weight: 550; }\n.mdw-toc-h2 { font-size: 0.95em; }\n.mdw-toc-h3 { font-size: 0.88em; opacity: 0.85; }\n\n/* 警告/提示块 */\n.mdw-admonition {\n  margin: 1.2em 0;\n  padding: 14px 18px;\n  border-radius: var(--shape-md);\n  border: 1px solid var(--outline-variant);\n}\n.mdw-admonition-title { font-weight: 600; margin: 0 0 6px; font-size: 1em; }\n.mdw-admonition-body { font-size: 0.95em; line-height: 1.7; }\n.mdw-admonition-body > *:first-child { margin-top: 0; }\n.mdw-admonition-body > *:last-child { margin-bottom: 0; }\n/* 各类型配色 */\n.mdw-admonition-note      { background: var(--note-bg); border-color: var(--note-border); color: var(--note-fg); }\n.mdw-admonition-tip       { background: var(--tip-bg); border-color: var(--tip-border); color: var(--tip-fg); }\n.mdw-admonition-info      { background: var(--info-bg); border-color: var(--info-border); color: var(--info-fg); }\n.mdw-admonition-warning   { background: var(--warning-bg); border-color: var(--warning-border); color: var(--warning-fg); }\n.mdw-admonition-danger    { background: var(--danger-bg); border-color: var(--danger-border); color: var(--danger-fg); }\n.mdw-admonition-important { background: var(--warning-bg); border-color: var(--warning-border); color: var(--warning-fg); }\n.mdw-admonition-caution   { background: var(--warning-bg); border-color: var(--warning-border); color: var(--warning-fg); }\n\n.mdw-content img { max-width: 100%; height: auto; border-radius: var(--shape-sm); }\n.mdw-content iframe { max-width: 100%; border-radius: var(--shape-sm); }\n\n/* 视频 / 音频 */\n.mdw-content video {\n  display: block;\n  max-width: 100%;\n  height: auto;\n  margin: 1.2em 0;\n  border-radius: var(--shape-md);\n  background: #000;\n  box-shadow: var(--elevation-1);\n}\n.mdw-content audio {\n  display: block;\n  width: 100%;\n  max-width: 560px;\n  margin: 1em 0;\n}\n\n/* 表格（Material 风格：仅底部边框 + 表头底色） */\n.mdw-content table,\n.mdw-content .mdw-table {\n  width: 100%;\n  border-collapse: collapse;\n  margin: 1.1em 0;\n  font-size: 0.95em;\n  display: block;\n  overflow-x: auto;\n}\n.mdw-content th,\n.mdw-content td {\n  padding: 12px 16px;\n  border-bottom: 1px solid var(--outline-variant);\n  text-align: left;\n}\n.mdw-content th { background: var(--surface-container-high); font-weight: 600; white-space: nowrap; }\n.mdw-content tr:last-child td { border-bottom: none; }\n\n/* 行内代码 / 代码块 */\n.mdw-content code {\n  font-family: var(--font-mono);\n  font-size: 0.88em;\n  background: var(--code-inline-bg);\n  color: var(--code-inline-text);\n  padding: 0.15em 0.45em;\n  border-radius: var(--shape-xs);\n}\n\n/* ── 增强代码块容器 ── */\n.mdw-code-block {\n  margin: 1.2em 0;\n  border-radius: var(--shape-md);\n  overflow: hidden;\n  box-shadow: var(--elevation-1);\n  background: var(--code-bg);\n}\n\n/* ── 语言标识栏 ── */\n.mdw-code-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 6px 12px 6px 16px;\n  background: rgba(255,255,255,0.06);\n  border-bottom: 1px solid rgba(255,255,255,0.08);\n  font-size: 12px;\n  font-weight: 500;\n  color: rgba(245,239,247,0.6);\n  letter-spacing: 0.04em;\n  user-select: none;\n}\n.mdw-code-lang {\n  text-transform: uppercase;\n  font-family: var(--font-mono);\n}\n\n/* ── 复制按钮 ── */\n.mdw-code-copy {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  padding: 4px 8px;\n  border: none;\n  border-radius: 4px;\n  background: transparent;\n  color: rgba(245,239,247,0.5);\n  cursor: pointer;\n  font-size: 12px;\n  transition: color 0.15s, background 0.15s;\n}\n.mdw-code-copy:hover {\n  color: rgba(245,239,247,0.9);\n  background: rgba(255,255,255,0.1);\n}\n.mdw-code-copy.mdw-copied {\n  color: #83d99e;\n}\n.mdw-code-copy svg { flex-shrink: 0; }\n\n/* ── 代码主体 ── */\n.mdw-code-block pre.mdw-code {\n  margin: 0;\n  padding: 16px 20px;\n  border-radius: 0;\n  box-shadow: none;\n  background: transparent;\n  color: var(--code-text);\n  font-size: 0.88em;\n  line-height: 1.65;\n  overflow-x: auto;\n}\n.mdw-code-block pre.mdw-code code {\n  background: transparent;\n  color: inherit;\n  padding: 0;\n  font-size: inherit;\n  line-height: inherit;\n}\n\n/* ── 选中颜色覆盖 ── */\n.mdw-code-block ::selection,\n.mdw-code-block pre ::selection,\n.mdw-code-block code ::selection {\n  background: rgba(149,117,205,0.32);\n  color: inherit;\n}\n\n/* ── 语法高亮 Token（Pygments material 主题） ── */\n.mdw-code-block .highlight { background: transparent; }\n.mdw-code-block .highlight .hll { background-color: #2C3B41 }\n.mdw-code-block .highlight .c { color: #546E7A; font-style: italic }\n.mdw-code-block .highlight .err { color: #FF5370 }\n.mdw-code-block .highlight .esc { color: #89DDFF }\n.mdw-code-block .highlight .k { color: #BB80B3 }\n.mdw-code-block .highlight .l { color: #C3E88D }\n.mdw-code-block .highlight .n { color: #EEFFFF }\n.mdw-code-block .highlight .o { color: #89DDFF }\n.mdw-code-block .highlight .p { color: #89DDFF }\n.mdw-code-block .highlight .ch { color: #546E7A; font-style: italic }\n.mdw-code-block .highlight .cm { color: #546E7A; font-style: italic }\n.mdw-code-block .highlight .cp { color: #546E7A; font-style: italic }\n.mdw-code-block .highlight .cpf { color: #546E7A; font-style: italic }\n.mdw-code-block .highlight .c1 { color: #546E7A; font-style: italic }\n.mdw-code-block .highlight .cs { color: #546E7A; font-style: italic }\n.mdw-code-block .highlight .gd { color: #FF5370 }\n.mdw-code-block .highlight .gi { color: #C3E88D }\n.mdw-code-block .highlight .go { color: #546E7A }\n.mdw-code-block .highlight .gp { color: #FFCB6B }\n.mdw-code-block .highlight .gs { color: #FF5370 }\n.mdw-code-block .highlight .gu { color: #89DDFF }\n.mdw-code-block .highlight .gt { color: #FF5370 }\n.mdw-code-block .highlight .kc { color: #89DDFF }\n.mdw-code-block .highlight .kd { color: #BB80B3 }\n.mdw-code-block .highlight .kn { color: #89DDFF; font-style: italic }\n.mdw-code-block .highlight .kp { color: #89DDFF }\n.mdw-code-block .highlight .kr { color: #BB80B3 }\n.mdw-code-block .highlight .kt { color: #BB80B3 }\n.mdw-code-block .highlight .m { color: #F78C6C }\n.mdw-code-block .highlight .s { color: #C3E88D }\n.mdw-code-block .highlight .na { color: #BB80B3 }\n.mdw-code-block .highlight .nb { color: #82AAFF }\n.mdw-code-block .highlight .nc { color: #FFCB6B }\n.mdw-code-block .highlight .no { color: #EEFFFF }\n.mdw-code-block .highlight .nd { color: #82AAFF }\n.mdw-code-block .highlight .ni { color: #89DDFF }\n.mdw-code-block .highlight .ne { color: #FFCB6B }\n.mdw-code-block .highlight .nf { color: #82AAFF }\n.mdw-code-block .highlight .nl { color: #82AAFF }\n.mdw-code-block .highlight .nn { color: #FFCB6B }\n.mdw-code-block .highlight .nx { color: #EEFFFF }\n.mdw-code-block .highlight .py { color: #FFCB6B }\n.mdw-code-block .highlight .nt { color: #FF5370 }\n.mdw-code-block .highlight .nv { color: #89DDFF }\n.mdw-code-block .highlight .ow { color: #89DDFF; font-style: italic }\n.mdw-code-block .highlight .mb { color: #F78C6C }\n.mdw-code-block .highlight .mf { color: #F78C6C }\n.mdw-code-block .highlight .mh { color: #F78C6C }\n.mdw-code-block .highlight .mi { color: #F78C6C }\n.mdw-code-block .highlight .mo { color: #F78C6C }\n.mdw-code-block .highlight .sa { color: #BB80B3 }\n.mdw-code-block .highlight .sb { color: #C3E88D }\n.mdw-code-block .highlight .sc { color: #C3E88D }\n.mdw-code-block .highlight .sd { color: #546E7A; font-style: italic }\n.mdw-code-block .highlight .s2 { color: #C3E88D }\n.mdw-code-block .highlight .se { color: #EEFFFF }\n.mdw-code-block .highlight .sh { color: #C3E88D }\n.mdw-code-block .highlight .si { color: #89DDFF }\n.mdw-code-block .highlight .sx { color: #C3E88D }\n.mdw-code-block .highlight .sr { color: #89DDFF }\n.mdw-code-block .highlight .s1 { color: #C3E88D }\n.mdw-code-block .highlight .ss { color: #89DDFF }\n.mdw-code-block .highlight .bp { color: #89DDFF }\n.mdw-code-block .highlight .fm { color: #82AAFF }\n.mdw-code-block .highlight .vc { color: #89DDFF }\n.mdw-code-block .highlight .vg { color: #89DDFF }\n.mdw-code-block .highlight .vi { color: #89DDFF }\n.mdw-code-block .highlight .vm { color: #82AAFF }\n.mdw-code-block .highlight .il { color: #F78C6C }\n\n/* ── 8. 信息块（tonal 卡片） ─────────────────────────── */\n.mdw-block {\n  padding: 16px 20px;\n  border-radius: var(--shape-md);\n  margin: 1.1em 0;\n  border: 1px solid var(--outline-variant);\n  background: var(--surface-container-low);\n  color: var(--on-surface-variant);\n  line-height: 1.7;\n  position: relative;\n}\n.mdw-block > :last-child { margin-bottom: 0; }\n.mdw-block strong { font-weight: 700; }\n\n.mdw-note { background: var(--note-bg); border-color: var(--note-border); color: var(--note-fg); }\n.mdw-info { background: var(--info-bg); border-color: var(--info-border); color: var(--info-fg); }\n.mdw-tip, .mdw-success { background: var(--tip-bg); border-color: var(--tip-border); color: var(--tip-fg); }\n.mdw-warning { background: var(--warning-bg); border-color: var(--warning-border); color: var(--warning-fg); }\n.mdw-danger, .mdw-error { background: var(--danger-bg); border-color: var(--danger-border); color: var(--danger-fg); }\n.mdw-important { background: var(--warning-bg); border-color: var(--warning-border); color: var(--warning-fg); }\n\n/* ── 9. 目录列表页（Material 卡片瓦片） ──────────────── */\n.mdw-dir-listing h1 { margin-bottom: 0.4em; }\n.mdw-dir-hint { color: var(--on-surface-variant); margin-bottom: 1.4em; }\n.mdw-dir-listing ul {\n  list-style: none;\n  padding: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n.mdw-dir-listing li { margin: 0; }\n.mdw-dir-listing li a {\n  position: relative;\n  display: flex;\n  align-items: center;\n  gap: 14px;\n  padding: 16px 20px;\n  border: 1px solid var(--outline-variant);\n  border-radius: var(--shape-md);\n  background: var(--surface-container-low);\n  color: var(--on-surface);\n  overflow: hidden;\n  transition: border-color 0.2s var(--ease-standard),\n              transform 0.25s var(--ease-emphasized),\n              box-shadow 0.25s var(--ease-standard);\n}\n.mdw-dir-listing li a:hover {\n  border-color: var(--outline);\n  text-decoration: none;\n  transform: translateY(-2px);\n  box-shadow: var(--elevation-2);\n}\n.mdw-dir-listing li a::after {\n  content: \"\";\n  width: 9px;\n  height: 9px;\n  border-right: 2px solid var(--on-surface-variant);\n  border-bottom: 2px solid var(--on-surface-variant);\n  transform: rotate(-45deg); /* ▸ 向右 */\n  margin-left: auto;\n  flex-shrink: 0;\n}\n.mdw-dir-icon { flex-shrink: 0; }\n\n/* ── 10. 页脚 ────────────────────────────────────────── */\n.mdw-footer {\n  margin-top: 4em;\n  padding-top: 1.2em;\n  border-top: 1px solid var(--outline-variant);\n  color: var(--on-surface-variant);\n  font-size: 0.85em;\n}\n.mdw-footer strong { color: var(--on-surface); }\n\n/* 错误页 */\n.mdw-error-detail {\n  background: var(--code-bg);\n  color: var(--code-text);\n  padding: 16px 20px;\n  border-radius: var(--shape-md);\n  overflow-x: auto;\n  font-family: var(--font-mono);\n  font-size: 0.88em;\n}\n\n/* ── 11. 移动端（抽屉式侧边栏） ──────────────────────── */\n.mdw-backdrop {\n  position: fixed;\n  inset: 0;\n  z-index: 55;\n  background: var(--scrim);\n  opacity: 0;\n  visibility: hidden;\n  transition: opacity 0.3s var(--ease-standard), visibility 0.3s;\n}\nbody.nav-open .mdw-backdrop { opacity: 1; visibility: visible; }\n\n@media (max-width: 899px) {\n  .mdw-nav {\n    width: min(85vw, 360px);\n    transform: translateX(-100%);\n    box-shadow: var(--elevation-3);\n  }\n  body.nav-open .mdw-nav { transform: translateX(0); }\n  body.nav-collapsed .mdw-nav { transform: translateX(-100%); }\n\n  .mdw-nav-close { display: block; }\n  .mdw-appbar { left: 0; }\n\n  .mdw-content {\n    margin-left: 0;\n    padding: calc(var(--appbar-h) + 20px) 18px 56px;\n    max-width: none;\n  }\n}\n\n/* ── 12. 涟漪与入场动效 ─────────────────────────────── */\n.mdw-ripple {\n  position: absolute;\n  border-radius: 50%;\n  background: currentColor;\n  opacity: 0.28;\n  transform: scale(0);\n  pointer-events: none;\n  animation: mdw-ripple 0.6s var(--ease-standard) forwards;\n}\n@keyframes mdw-ripple {\n  to { transform: scale(1); opacity: 0; }\n}\n\n@keyframes mdw-fade-up {\n  from { opacity: 0; transform: translateY(14px); }\n  to { opacity: 1; transform: none; }\n}\n\n/* ── 13. 无障碍：尊重系统减弱动态设置 ────────────────── */\n@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after {\n    animation-duration: 0.01ms !important;\n    animation-iteration-count: 1 !important;\n    transition-duration: 0.01ms !important;\n    scroll-behavior: auto !important;\n  }\n}\n\n/* ── 14. 打印 ────────────────────────────────────────── */\n@media print {\n  .mdw-nav, .mdw-sidenav-btn, .mdw-backdrop, .mdw-appbar { display: none !important; }\n  .mdw-content { margin-left: 0; max-width: none; }\n  body { background: #fff; color: #000; }\n}\n\n/* ── 15. 并排布局（row / col 自定义块） ────────────── */\n\n/* 页面加载时禁用折叠动画过渡，避免脚本恢复状态前的\"展开→收起\"闪烁 */\n.mdw-no-transition .mdw-nav-tree-wrap,\n.mdw-no-transition .mdw-nav-tree-inner { transition: none !important; }\n\n.mdw-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 16px;\n  margin: 1.2em 0;\n}\n.mdw-col {\n  flex: 1;\n  min-width: 240px;\n  padding: 16px 20px;\n  border-radius: var(--shape-md);\n  border: 1px solid var(--outline-variant);\n  background: var(--surface-container-low);\n}\n.mdw-col > :first-child { margin-top: 0; }\n.mdw-col > :last-child { margin-bottom: 0; }\n\n/* 删除线、标记文本 */\n.mdw-content del { text-decoration: line-through; opacity: 0.7; }\n.mdw-content mark { background: var(--primary-container); color: var(--on-primary-container); padding: 0.1em 0.3em; border-radius: 2px; }\n"
APP_JS = "/* MDW 前端交互\n * 1. 侧边栏：桌面端收起/展开（记忆偏好），移动端抽屉开合\n * 2. 分组折叠：点击箭头或目录标题切换（grid 缓动动画），状态持久化并跨页面保持\n * 3. 侧边栏滚动位置记忆：切换页面后恢复滚动位置\n * 4. 顶栏：滚动时浮现阴影\n * 5. Material 涟漪效果（尊重 prefers-reduced-motion）\n */\n(function () {\n  'use strict';\n\n  var nav = document.getElementById('mdw-nav');\n  var navBody = nav && nav.querySelector('.mdw-nav-body');\n  var btn = document.getElementById('mdw-sidenav-btn');\n  var closeBtn = document.getElementById('mdw-nav-close');\n  var backdrop = document.getElementById('mdw-backdrop');\n  var appbar = document.getElementById('mdw-appbar');\n  var body = document.body;\n\n  var KEY_NAV = 'mdw:nav-collapsed';\n  var KEY_PREFIX = 'mdw:collapse:';\n  var KEY_SCROLL = 'mdw:sidebar-scroll';\n  var mobile = window.matchMedia('(max-width: 899px)');\n  var reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)');\n\n  function readLS(key) {\n    try { return localStorage.getItem(key); } catch (e) { return null; }\n  }\n  function writeLS(key, value) {\n    try { localStorage.setItem(key, value); } catch (e) { /* 隐私模式忽略 */ }\n  }\n\n  /* ── 侧边栏：桌面收起 / 移动抽屉 ─────────────────── */\n  function setDesktopCollapsed(collapsed) {\n    body.classList.toggle('nav-collapsed', !!collapsed);\n    if (btn) btn.setAttribute('aria-expanded', collapsed ? 'false' : 'true');\n    writeLS(KEY_NAV, collapsed ? '1' : '0');\n  }\n\n  function applyDesktopState() {\n    if (!mobile.matches) setDesktopCollapsed(readLS(KEY_NAV) === '1');\n  }\n\n  function openDrawer() {\n    body.classList.add('nav-open');\n    if (btn) btn.setAttribute('aria-expanded', 'true');\n  }\n  function closeDrawer() {\n    body.classList.remove('nav-open');\n  }\n\n  if (btn) btn.addEventListener('click', function () {\n    if (mobile.matches) {\n      body.classList.contains('nav-open') ? closeDrawer() : openDrawer();\n    } else {\n      setDesktopCollapsed(!body.classList.contains('nav-collapsed'));\n    }\n  });\n\n  if (closeBtn) closeBtn.addEventListener('click', closeDrawer);\n  if (backdrop) backdrop.addEventListener('click', closeDrawer);\n  document.addEventListener('keydown', function (e) {\n    if (e.key === 'Escape') closeDrawer();\n  });\n\n  /* ── 分组折叠 ─────────────────────────────────────── */\n  function toggleGroup(group, collapsed) {\n    group.classList.toggle('collapsed', !!collapsed);\n    var toggle = group.querySelector('.mdw-nav-toggle');\n    if (toggle) toggle.setAttribute('aria-expanded', collapsed ? 'false' : 'true');\n    writeLS(KEY_PREFIX + (group.getAttribute('data-path') || ''), collapsed ? '1' : '0');\n  }\n\n  if (nav) {\n    nav.addEventListener('click', function (e) {\n      var target = e.target.closest('.mdw-nav-toggle, .mdw-nav-dir');\n      if (!target) return;\n      var group = target.closest('.mdw-nav-group');\n      if (!group) return;\n      toggleGroup(group, !group.classList.contains('collapsed'));\n    });\n\n    nav.addEventListener('keydown', function (e) {\n      if (e.key !== 'Enter' && e.key !== ' ') return;\n      var target = e.target.closest('.mdw-nav-dir');\n      if (!target) return;\n      e.preventDefault();\n      var group = target.closest('.mdw-nav-group');\n      if (!group) return;\n      toggleGroup(group, !group.classList.contains('collapsed'));\n    });\n\n    // 移动端：点击链接后自动关闭抽屉\n    nav.addEventListener('click', function (e) {\n      if (mobile.matches && e.target.closest('a')) closeDrawer();\n    });\n  }\n\n  /* ── 路径匹配工具 ────────────────────────────────── */\n  function activePath() {\n    if (!nav) return '';\n    // 优先从 a.active 获取，兼容 .mdw-nav-dir.active\n    var link = nav.querySelector('a.active');\n    if (link) return link.getAttribute('href') || '';\n    var dir = nav.querySelector('.mdw-nav-dir.active');\n    if (dir) {\n      var group = dir.closest('.mdw-nav-group');\n      return group ? (group.getAttribute('data-path') || '') : '';\n    }\n    return '';\n  }\n\n  function groupContains(group, path) {\n    if (!path) return false;\n    var dp = (group.getAttribute('data-path') || '').replace(/\\/+$/, '');\n    var p = path.replace(/\\/+$/, '');\n    return !!dp && (p === dp || p.indexOf(dp + '/') === 0);\n  }\n\n  /* ── 恢复折叠偏好（在DOM解析后立即执行，避免闪烁） ── */\n  if (nav) {\n    var active = activePath();\n    nav.querySelectorAll('.mdw-nav-group[data-path]').forEach(function (group) {\n      if (readLS(KEY_PREFIX + group.getAttribute('data-path')) !== '1') return;\n      if (groupContains(group, active)) return;\n      toggleGroup(group, true);\n    });\n  }\n\n  // 折叠状态恢复完毕，启用过渡动画\n  requestAnimationFrame(function () {\n    document.documentElement.classList.remove('mdw-no-transition');\n  });\n\n  /* ── 侧边栏滚动位置记忆 ──────────────────────────── */\n  function saveScroll() {\n    if (navBody) writeLS(KEY_SCROLL, String(navBody.scrollTop || 0));\n  }\n  function restoreScroll() {\n    if (!navBody) return;\n    var saved = parseInt(readLS(KEY_SCROLL) || '0', 10);\n    if (saved > 0) {\n      navBody.scrollTop = saved;\n    } else {\n      // 无保存值时，滚动到当前激活项可见\n      var active = navBody.querySelector('.mdw-nav-link.active, .mdw-nav-dir.active');\n      if (active) active.scrollIntoView({ block: 'nearest' });\n    }\n  }\n\n  // 离开页面前保存滚动位置\n  window.addEventListener('beforeunload', saveScroll);\n  // 页面加载后恢复\n  restoreScroll();\n\n  /* ── 顶栏：滚动时浮现阴影 ────────────────────────── */\n  function onScroll() {\n    var y = window.pageYOffset || document.documentElement.scrollTop || 0;\n    if (appbar) appbar.classList.toggle('scrolled', y > 4);\n  }\n  window.addEventListener('scroll', onScroll, { passive: true });\n  onScroll();\n\n  /* ── Material 涟漪效果 ───────────────────────────── */\n  function attachRipple(el) {\n    if (!el || reduceMotion.matches) return;\n    el.addEventListener('pointerdown', function (e) {\n      var rect = el.getBoundingClientRect();\n      var size = Math.max(rect.width, rect.height) * 2;\n      var ripple = document.createElement('span');\n      ripple.className = 'mdw-ripple';\n      ripple.style.width = ripple.style.height = size + 'px';\n      ripple.style.left = (e.clientX - rect.left - size / 2) + 'px';\n      ripple.style.top = (e.clientY - rect.top - size / 2) + 'px';\n      el.appendChild(ripple);\n      ripple.addEventListener('animationend', function () {\n        if (ripple.parentNode) ripple.parentNode.removeChild(ripple);\n      });\n    });\n  }\n\n  if (nav) {\n    nav.querySelectorAll('.mdw-nav-row').forEach(attachRipple);\n  }\n  if (btn) attachRipple(btn);\n  if (closeBtn) attachRipple(closeBtn);\n  Array.prototype.forEach.call(\n    document.querySelectorAll('.mdw-dir-listing li a'),\n    attachRipple\n  );\n\n  /* ── 视口变化同步 ───────────────────────────────── */\n  mobile.addEventListener('change', function (e) {\n    if (e.matches) {\n      closeDrawer();\n      body.classList.remove('nav-collapsed');\n    } else {\n      applyDesktopState();\n    }\n  });\n\n  /* ── 页面跳转卡片：连续相邻的卡片自动并排为网格 ── */\n  function groupPageCards() {\n    var cards = document.querySelectorAll(\n      '.mdw-content > .mdw-block.mdw-page-card'\n    );\n    for (var i = 0; i < cards.length; i++) {\n      var first = cards[i];\n      var parent = first.parentNode;\n      if (parent.classList.contains('mdw-page-card-grid')) continue;\n      var group = [first];\n      var cur = first;\n      while (\n        cur.nextElementSibling &&\n        cur.nextElementSibling.classList.contains('mdw-block') &&\n        cur.nextElementSibling.classList.contains('mdw-page-card')\n      ) {\n        cur = cur.nextElementSibling;\n        group.push(cur);\n      }\n      if (group.length < 2) continue;\n      var grid = document.createElement('div');\n      grid.className = 'mdw-page-card-grid';\n      parent.insertBefore(grid, first);\n      group.forEach(function (card) { grid.appendChild(card); });\n      i += group.length - 1;\n    }\n  }\n  groupPageCards();\n\n  applyDesktopState();\n\n  /* ── 代码复制（全局可访问） ─────────────────────── */\n  window.MDW = window.MDW || {};\n  window.MDW.copyCode = function (btn) {\n    var block = btn.closest('.mdw-code-block');\n    if (!block) return;\n    var codeEl = block.querySelector('code');\n    if (!codeEl) return;\n    var text = codeEl.textContent || '';\n    if (navigator.clipboard && navigator.clipboard.writeText) {\n      navigator.clipboard.writeText(text).then(function () {\n        btn.classList.add('mdw-copied');\n        setTimeout(function () { btn.classList.remove('mdw-copied'); }, 1800);\n      });\n    } else {\n      // 回退：创建临时 textarea\n      var ta = document.createElement('textarea');\n      ta.value = text;\n      ta.style.position = 'fixed';\n      ta.style.opacity = '0';\n      document.body.appendChild(ta);\n      ta.select();\n      try { document.execCommand('copy'); } catch (e) {}\n      document.body.removeChild(ta);\n      btn.classList.add('mdw-copied');\n      setTimeout(function () { btn.classList.remove('mdw-copied'); }, 1800);\n    }\n  };\n\n  /* ── 标题锚点：点击 # 复制链接 ───────────────────── */\n  document.addEventListener('click', function (e) {\n    var h = e.target.closest('h1[id],h2[id],h3[id],h4[id],h5[id],h6[id]');\n    if (!h || !h.id) return;\n    // 仅当点击位置在标题文字左侧（# 图标区域）时触发\n    var rect = h.getBoundingClientRect();\n    var clickX = e.clientX - rect.left;\n    if (clickX > 24) return;  // 超出 # 图标范围不触发\n    var url = window.location.origin + window.location.pathname + '#' + h.id;\n    if (navigator.clipboard && navigator.clipboard.writeText) {\n      navigator.clipboard.writeText(url).then(function () {\n        showAnchorToast(h);\n      });\n    } else {\n      var ta = document.createElement('textarea');\n      ta.value = url;\n      ta.style.position = 'fixed'; ta.style.opacity = '0';\n      document.body.appendChild(ta); ta.select();\n      try { document.execCommand('copy'); } catch (e) {}\n      document.body.removeChild(ta);\n      showAnchorToast(h);\n    }\n  });\n\n  function showAnchorToast(h) {\n    var toast = document.createElement('span');\n    toast.className = 'mdw-anchor-toast';\n    toast.textContent = '链接已复制';\n    var rect = h.getBoundingClientRect();\n    toast.style.cssText = 'position:absolute;left:0;top:-24px;font-size:11px;color:var(--primary);opacity:0;transition:opacity 0.2s;white-space:nowrap;pointer-events:none;';\n    h.style.position = h.style.position || 'relative';\n    h.appendChild(toast);\n    requestAnimationFrame(function () { toast.style.opacity = '1'; });\n    setTimeout(function () {\n      toast.style.opacity = '0';\n      setTimeout(function () { if (toast.parentNode) toast.parentNode.removeChild(toast); }, 200);\n    }, 1500);\n  }\n})();"
